#ifndef REGISTER_HPP
#define REGISTER_HPP

template <typename T>
class Register {
public:
  T prev;
  T next;
  bool _stall;

  Register() : prev(T()), next(T()), _stall(false) {}

  Register(T d) : prev(d), next(d), _stall(false) {}

  T read() {
    return prev;
  }

  T current() {
    return next;
  }

  void write(const T &t) {
    next = t;
  }

  void tick() {
    if (!_stall) {
      prev = next;
    }
  }

  void stall(bool stall) {
    _stall = stall;
  }

  operator T() {
    return read();
  }

  void operator=(T next) {
    this->next = next;
  }
};

#endif // REGISTER_HPP
